#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int turnNum;
    cin >> turnNum;
    vector<int> aliceChoices, bobChoices;
    int n;
    for (cin >> n; n--;) {
        int x; cin >> x;
        aliceChoices.push_back(x);
    }
    for (cin >> n; n--;) {
        int x; cin >> x;
        bobChoices.push_back(x);
    }
    // Rotate bobChoices by one position
    rotate(bobChoices.begin(), bobChoices.begin() + 1, bobChoices.end());

    int minWin = 0, maxWin = 0;

    for (size_t i = 0; i < aliceChoices.size(); ++i) {
        maxWin += min(aliceChoices[i], bobChoices[i]);
    }

    int max_bob = *max_element(bobChoices.begin(), bobChoices.end());
    for (size_t i = 0; i < bobChoices.size(); ++i) {
        if (bobChoices[i] == max_bob && bobChoices[i] + aliceChoices[i] > minWin) {
            minWin = bobChoices[i] + aliceChoices[i];
        }
    }

    int max_alice = *max_element(aliceChoices.begin(), aliceChoices.end());
    for (size_t i = 0; i < aliceChoices.size(); ++i) {
        if (aliceChoices[i] == max_alice && aliceChoices[i] + bobChoices[i] > minWin) {
            minWin = aliceChoices[i] + bobChoices[i];
        }
    }

    if (minWin > turnNum) {
        minWin -= turnNum;
    } else {
        minWin = 0;
    }

    cout << minWin << " " << maxWin << "\n";

    return 0;
}
